#!/usr/bin/env python3
"""Writes tests/gui/widgets/RibbonPins.h from RibbonProbe's output.

usage: gen_ribbon_pins.py PROBE_OUTPUT HEADER COMMIT

PROBE_OUTPUT is the probe's standard output (generate.sh sends OpenRocket's log to standard error).
"""
import os
import pathlib
import subprocess
import sys

HEADER_TOP = """#pragma once

// GENERATED by tools/openrocket-gui-pins/generate.sh (ribbon/gen_ribbon_pins.py from the output of
// ribbon/probe/RibbonProbe.java: OpenRocket's StageSelector and ConfigurationComboBox, made as
// RocketPanel makes them, headless with SwingPreferences and FlatLaf Light; see
// ribbon_golden_tests.cpp); do not edit.

#include <array>
#include <ostream>
#include <span>
#include <string_view>

namespace QtRocket::Gui::Test
{{

/// The OpenRocket commit the pins come from.
inline constexpr std::string_view kRibbonPinsCommit = "{commit}";

/// The tooltip of a stage button: RocketPanel.btn.Stages.Toggle.ttip, .LastActive.ttip or
/// .NoChildren.ttip.
enum class StageButtonTip
{{
    TOGGLE,
    LAST_ACTIVE,
    NO_CHILDREN,
}};

/// A stage button as OpenRocket's StageSelector shows it.
struct StageButtonPin
{{
    /// The stage's name.
    std::string_view text;
    bool             selected;
    bool             enabled;
    /// Whether the font is italic.
    bool italic;
    /// Whether the icon is Icons.COMPONENT_DISABLED (else there is none).
    bool           inactiveIcon;
    StageButtonTip tip;
}};

/// A document's undo history: its number of states, the position in it, isUndoAvailable() (the
/// description of the step to undo is null in every pin).
struct UndoPin
{{
    int  states;
    int  position;
    bool available;
}};

/// A click on a stage button (doClick()) and what followed: the change events the rocket's
/// listeners received (every one from the rocket), the buttons and which stages are active in
/// the selected configuration ('1' for isStageActive(n), n = 0 .. stages - 1).
struct StageClickPin
{{
    /// Whether the click is the first on a design made anew.
    bool fresh;
    int  button;
    /// The number of events and their type (0 without one).
    int eventCount;
    int eventType;
    /// Whether the design is a document, whose undo history is pinned before and after.
    bool                            document;
    UndoPin                         undoBefore;
    UndoPin                         undoAfter;
    std::span<const StageButtonPin> buttons;
    std::string_view                activeStages;
}};

/// An item of the configuration combo box picked (setSelectedItem(), as the popup does) and what
/// followed: the change events (every one from the rocket), the combo box's selected item, the
/// rocket's selected configuration (both as item indices) and the selected item's text.
struct ConfigurationPickPin
{{
    int              item;
    int              eventCount;
    int              eventType;
    int              selected;
    int              rocketSelected;
    std::string_view selectedText;
}};

/// One design: its stage buttons, clicked, and its configuration combo box, picked. A design of
/// source "local" has only the combo box, made with updateRocketConfig false.
struct RibbonScenarioPin
{{
    /// The scenario's name in the probe: "<source>:<design>".
    std::string_view name;
    /// The scenario as a test name: letters and digits.
    std::string_view testName;
    /// "example" (a file of data/examples), "testrocket" (a TestRockets maker), "special" (a
    /// design of the probe: see ribbon_golden_tests.cpp) or "local".
    std::string_view                        source;
    std::string_view                        design;
    std::span<const StageButtonPin>         buttons;
    std::string_view                        activeStages;
    std::span<const StageClickPin>          clicks;
    std::span<const std::string_view>       items;
    int                                     selectedItem;
    std::span<const ConfigurationPickPin>   picks;
}};

/// What GoogleTest prints for the scenario of a test that failed: its name.
// NOLINTNEXTLINE(readability-identifier-naming): the name GoogleTest looks for
inline void PrintTo(const RibbonScenarioPin& pin, std::ostream* out)
{{
    *out << pin.name;
}}

// clang-format off
// NOLINTBEGIN(modernize-use-designated-initializers): tables printed by the Java probe
// NOLINTBEGIN(modernize-raw-string-literal): the texts escaped alike, quotes and UTF-8 bytes
"""

HEADER_BOTTOM = """// NOLINTEND(modernize-raw-string-literal)
// NOLINTEND(modernize-use-designated-initializers)
// clang-format on

}  // namespace QtRocket::Gui::Test
"""

TIPS = {"toggle": "StageButtonTip::TOGGLE", "lastActive": "StageButtonTip::LAST_ACTIVE",
        "noChildren": "StageButtonTip::NO_CHILDREN"}


def cpp_string(text):
    out = ['"']
    for ch in text:
        if ch in '"\\':
            out.append("\\" + ch)
        elif 0x20 <= ord(ch) < 0x7F:
            if out[-1].startswith("\\x") and ch in "0123456789abcdefABCDEF":
                # A hex digit after an escape would continue it.
                out.append('" "')
            out.append(ch)
        else:
            # UTF-8 bytes as escapes (the core's texts are UTF-8 std::string).
            for byte in ch.encode("utf-8"):
                out.append("\\x%02X" % byte)
    out.append('"')
    return "".join(out)


def ident(name):
    words = []
    word = ""
    for ch in name:
        if ch.isalnum():
            word += ch
        else:
            if word:
                words.append(word)
            word = ""
    if word:
        words.append(word)
    return "".join(w[0].upper() + w[1:] for w in words)


def boolean(bit):
    return {"1": "true", "0": "false"}[bit]


def parse(lines):
    scenarios = []
    current = None
    click = None
    pick = None
    fresh = False
    pending_undo = None
    for line in lines:
        line = line.rstrip("\n")
        if line.startswith("D "):
            current = {"name": line[2:], "buttons": [], "flags": "", "clicks": [], "items": [],
                       "selected": -1, "picks": []}
            scenarios.append(current)
            click = pick = None
        elif line == "N":
            fresh = True
            pending_undo = None
            click = None
        elif line.startswith("U "):
            parts = line[2:].split(" ")
            if parts[3] != "null":
                raise SystemExit("unexpected undo description: " + line)
            undo = (int(parts[0]), int(parts[1]), parts[2] == "true")
            if click is None:
                pending_undo = undo
            else:
                click["undoAfter"] = undo
        elif line.startswith("K "):
            before = pending_undo
            if click is not None and "undoAfter" in click:
                before = click["undoAfter"]
            click = {"fresh": fresh, "button": int(line[2:]), "events": [], "undoBefore": before,
                     "buttons": [], "flags": ""}
            current["clicks"].append(click)
            fresh = False
            pending_undo = None
        elif line.startswith("E "):
            event_type, source = line[2:].split(" ")
            if source != "Rocket":
                raise SystemExit("unexpected event source: " + line)
            target = pick if pick is not None else click
            target["events"].append(int(event_type))
        elif line.startswith("B "):
            head, text = line[2:].split(" | ", 1)
            _, selected, enabled, italic, icon, tip = head.split(" ")
            if icon not in ("none", "disabled"):
                raise SystemExit("unexpected icon: " + line)
            button = (text, selected, enabled, italic, icon == "disabled", TIPS[tip])
            (click["buttons"] if click is not None else current["buttons"]).append(button)
        elif line.startswith("F "):
            if click is not None:
                click["flags"] = line[2:]
            else:
                current["flags"] = line[2:]
        elif line.startswith("C "):
            size, selected = line[2:].split(" ")
            current["selected"] = int(selected)
            click = None
        elif line.startswith("I "):
            head, text = line[2:].split(" | ", 1)
            if int(head) != len(current["items"]):
                raise SystemExit("items out of order: " + line)
            current["items"].append(text)
        elif line.startswith("P "):
            pick = {"item": int(line[2:]), "events": []}
            current["picks"].append(pick)
        elif line.startswith("S "):
            head, text = line[2:].split(" | ", 1)
            selected, rocket_selected = head.split(" ")
            pick["selected"] = int(selected)
            pick["rocketSelected"] = int(rocket_selected)
            pick["text"] = text
            pick = None
        elif line == "L":
            current = click = pick = None
        else:
            raise SystemExit("unexpected line: " + line)
    return scenarios


def events_of(events):
    if len(events) > 1:
        raise SystemExit("more than one event: %r" % events)
    return (len(events), events[0] if events else 0)


def button_rows(buttons):
    return ["    {%s, %s, %s, %s, %s, %s}," % (cpp_string(text), boolean(selected), boolean(enabled),
                                              boolean(italic), "true" if icon else "false", tip)
            for text, selected, enabled, italic, icon, tip in buttons]


def undo_text(undo):
    if undo is None:
        return "{0, 0, false}"
    return "{%d, %d, %s}" % (undo[0], undo[1], "true" if undo[2] else "false")


def array(out, element, name, rows):
    """Appends the table @p name of @p rows (each a line of the header)."""
    if not rows:
        out.append("inline constexpr std::array<%s, 0> %s{};" % (element, name))
        return
    out.append("inline constexpr std::array<%s, %d> %s{{" % (element, len(rows), name))
    out.extend(rows)
    out.append("}};")


def main():
    probe, header, commit = sys.argv[1:4]
    with open(probe, encoding="utf-8") as f:
        scenarios = parse(f.readlines())

    out = [HEADER_TOP.format(commit=commit)]
    table = []
    for scenario in scenarios:
        name = ident(scenario["name"])
        source, design = scenario["name"].split(":", 1)
        buttons = "kStageButtons" + name
        array(out, "StageButtonPin", buttons, button_rows(scenario["buttons"]))
        click_rows = []
        for index, click in enumerate(scenario["clicks"]):
            click_buttons = "kStageButtons%sClick%d" % (name, index)
            array(out, "StageButtonPin", click_buttons, button_rows(click["buttons"]))
            count, event_type = events_of(click["events"])
            document = click["undoBefore"] is not None
            if document != ("undoAfter" in click):
                raise SystemExit("undo history before and after differ in " + scenario["name"])
            click_rows.append("    {%s, %d, %d, %d, %s, %s, %s, %s, %s}," % (
                "true" if click["fresh"] else "false", click["button"], count, event_type,
                "true" if document else "false", undo_text(click["undoBefore"]),
                undo_text(click.get("undoAfter")), click_buttons, cpp_string(click["flags"])))
        clicks = "kStageClicks" + name
        array(out, "StageClickPin", clicks, click_rows)
        items = "kConfigurationItems" + name
        array(out, "std::string_view", items, ["    %s," % cpp_string(item) for item in scenario["items"]])
        picks = "kConfigurationPicks" + name
        pick_rows = []
        for pick in scenario["picks"]:
            count, event_type = events_of(pick["events"])
            pick_rows.append("    {%d, %d, %d, %d, %d, %s}," % (
                pick["item"], count, event_type, pick["selected"], pick["rocketSelected"], cpp_string(pick["text"])))
        array(out, "ConfigurationPickPin", picks, pick_rows)
        table.append("    {%s, %s, %s, %s, %s, %s, %s, %s, %d, %s}," % (
            cpp_string(scenario["name"]), cpp_string(name), cpp_string(source), cpp_string(design), buttons,
            cpp_string(scenario["flags"]), clicks, items, scenario["selected"], picks))
    array(out, "RibbonScenarioPin", "kRibbonScenarios", table)
    out.append(HEADER_BOTTOM)
    with open(header, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(out))
    # The repository's style (its .clang-format, wherever the header is written: generate.sh
    # --check writes it into a temporary directory), so that a run reproduces the committed
    # header byte for byte.
    style = pathlib.Path(__file__).resolve().parents[3] / ".clang-format"
    clang_format = os.environ.get("CLANG_FORMAT", "clang-format")
    subprocess.run([clang_format, "-i", f"--style=file:{style}", header], check=True)


if __name__ == "__main__":
    main()
